#!/usr/bin/env python3
"""Create the new prospective V3 scan/proxy contract and blocker audit."""
from __future__ import annotations
import csv, hashlib, json, subprocess
from datetime import datetime, timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'outputs/v3_scan_proxy_preregistration_v1'
BASE=ROOT/'outputs/accelerated_event_query_v1/oracle_protocol_v3_model_relative'; V7=BASE/'full_grid_preregistration_staged_v7_review_corrections'
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for x in iter(lambda:f.read(1<<20),b''):h.update(x)
 return h.hexdigest()
def canonical(x): return hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def j(path,x):path.write_text(json.dumps(x,indent=2,sort_keys=True)+'\n')
def c(path,rows):
 with path.open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def main():
 OUT.mkdir(parents=True,exist_ok=True); created=datetime.now(timezone.utc).isoformat(); model=ROOT/'models/yolo/yolov8n.pt'
 sources={'runner':sha(ROOT/'scripts/run_v3_prospective_scan_proxy.py'),'finalizer':sha(ROOT/'scripts/finalize_v3_prospective_scan_proxy.py'),'unit_manifest':sha(V7/'FULL_GRID_UNIT_MANIFEST.json'),'video_manifest':sha(ROOT/'outputs/accelerated_event_query_v1/video_manifests/frozen_videos_v1.json'),'runtime_models':sha(ROOT/'configs/runtime_models.yaml')}
 protocol={'contract_type':'NEW_PROSPECTIVE_PREREGISTRATION','THIS_IS_NOT_A_RECOVERED_HISTORICAL_PREREGISTRATION':True,'created_at_utc':created,'PROTOCOL_FROZEN':True,'DOWNSTREAM_RESULTS_OBSERVED':False,'reference_GT_used_for_parameter_choice':False,'materializer_results_used':False,'selector_results_used':False,'source_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'dirty_worktree':subprocess.check_output(['git','status','--porcelain'],cwd=ROOT,text=True).splitlines(),'video_ids':['DALI','HANGZHOU','WUHAN'],'video_manifest_path':'outputs/accelerated_event_query_v1/video_manifests/frozen_videos_v1.json','unit_manifest_path':'outputs/accelerated_event_query_v1/oracle_protocol_v3_model_relative/full_grid_preregistration_staged_v7_review_corrections/FULL_GRID_UNIT_MANIFEST.json','implementation':{'name':'prospective_unit_midpoint_yolov8n_proxy_v1','runner_path':'scripts/run_v3_prospective_scan_proxy.py','finalizer_path':'scripts/finalize_v3_prospective_scan_proxy.py','selection_reason':'simplest maintained repository-compatible YOLO interface; one deterministic unit-local sample; no semantic-oracle/reference input; stable one-candidate-per-V3-unit identity','historical_config_promotion':False},'sampling':{'unitization':'frozen V7 unit manifest','sample_rule':'one midpoint timestamp per V3 unit: start_sec + duration_seconds / 2','decode_backend':'OpenCV VideoCapture; seek by CAP_PROP_POS_MSEC then sequential read','first_last_behavior':'midpoint is strictly inside every nonempty unit; decode failure is terminal and not coerced','future_visual_context':'offline-video-query-visible single midpoint frame; no future semantic outcome'},'model':{'name':'YOLOv8n','source':'Ultralytics','weight_path':'models/yolo/yolov8n.pt','weight_sha256':'f59b3d833e2ff32e194b5bb8e08d211dc7c5bdf144b90d2c8412c47ccfc83b36','weight_available_at_freeze':model.is_file(),'runtime':'ultralytics==8.4.51 (previously fixed non-target engineering runtime; new prospective binding)','device':'cuda:0','precision':'backend_default_FP32','input_resolution':640,'confidence_threshold':0.25,'nms_iou':0.45,'max_detections':300,'class_filter':[0,1,2,3,5,7],'THRESHOLD_NOT_TUNED_ON_EVALUATION_VIDEOS':True},'candidate_semantics':{'candidate_type':'frozen_v3_unit','candidate_id':'{video_id}::{unit_id}','temporal_support':'exact frozen V3 unit interval','creation_rule':'exactly one candidate for every frozen V3 unit','dedup_rule':'unit ID uniqueness; duplicates fail finalization','ordering_rule':'frozen unit ordinal'},'proxy_semantics':{'features':{'det_count':'number of retained COCO classes at deterministic midpoint','max_conf':'maximum retained detector confidence','conf_sum':'sum of retained detector confidences','proxy_score':'0.5 * min(det_count, 20) / 20 + 0.5 * max_conf'},'normalization':'none; raw bounded score','uses_semantic_oracle':False,'uses_reference_GT':False,'uses_future_semantic_outcome':False},'output':{'raw_schema':'one JSON record per frozen unit','candidate_table':'Parquet','proxy_table':'Parquet','finalizer':'deterministic sort by unit_id then immutable tables'},'source_hashes':sources}
 protocol['protocol_hash']=canonical(protocol); j(OUT/'FROZEN_V3_SCAN_PROXY_PROTOCOL.json',protocol); (OUT/'PROTOCOL_HASH.txt').write_text(protocol['protocol_hash']+'\n')
 (OUT/'IMPLEMENTATION_OPTIONS.md').write_text("# Implementation Options\n\n| implementation | status | reason |\n|---|---|---|\n| `src/garc_eval/models/yolo_scorer.py` | maintained but single-class frame scorer | insufficient direct multi-class unit-table finalization alone |\n| `scripts/partial_scan_pilot_common.py` | historical maintained | different cut-in query/reference; not promoted |\n| `scripts/run_mfrp_previews.py` | historical maintained | different preview study; not promoted |\n| `scripts/run_v3_prospective_scan_proxy.py` | selected new prospective wrapper | binds frozen V3 units to simple YOLOv8n midpoint proxy without semantic inputs |\n\nSelection used interface, deterministic identity, cheapness, and causal availability only; no downstream result was read.\n")
 (OUT/'PREREGISTRATION_DECISION.md').write_text(f"# V3 Scan/Proxy Preregistration Decision\n\nCreated prospectively on: `{created}`\n\nHistorical contract existed: `NO`\n\nDownstream P0 results viewed before freeze: `NO`\n\nReference GT used for parameter choice: `NO`\n\nMaterializer results used: `NO`\n\nSelector results used: `NO`\n\nChosen implementation: `prospective_unit_midpoint_yolov8n_proxy_v1`\n\nReason: simplest maintained V3-unit-compatible cheap scan wrapper with stable candidate identity and no semantic input.\n\nProtocol hash: `{protocol['protocol_hash']}`\n")
 j(OUT/'CANDIDATE_SCHEMA.json',{'fields':['video_id','candidate_id','start_sec','end_sec','source_unit_ids','candidate_type','candidate_order'],'semantic_oracle_forbidden':True});j(OUT/'PROXY_SCHEMA.json',{'fields':['video_id','candidate_id','det_count','max_conf','conf_sum','proxy_score','protocol_hash'],'semantic_oracle_forbidden':True})
 aud=[]
 for f in ['video_id','candidate_id','start_sec','end_sec','source_unit_ids','candidate_type','candidate_order','det_count','max_conf','conf_sum','proxy_score','protocol_hash']:aud.append({'field':f,'available_before_expensive_semantic_query':True,'derived_from_reference':False,'derived_from_future_semantic_result':False,'contains_posthoc_event_identity':False,'allowed':True,'status':'PASS'})
 c(OUT/'SELECTOR_VISIBILITY_AUDIT.csv',aud)
 rows=[]
 for vid,n in [('DALI',567),('HANGZHOU',561),('WUHAN',347)]:
  j(OUT/f'{vid}_SCAN_MANIFEST.json',{'status':'NOT_EXECUTED_TRUE_BLOCKER_WEIGHT_MISSING','video_id':vid,'protocol_hash':protocol['protocol_hash'],'expected_units':n,'raw_rows':0,'candidate_rows':0,'proxy_rows':0,'weight_available':model.is_file()});rows.append({'video_id':vid,'expected_scanned_timestamps':n,'observed_scanned_timestamps':0,'missing_timestamps':n,'duplicate_candidate_ids':0,'invalid_temporal_ranges':0,'nan_inf_proxy_fields':0,'schema_violations':0,'status':'NOT_EXECUTED_WEIGHT_MISSING'})
 c(OUT/'SCAN_COMPLETENESS.csv',rows);c(OUT/'SCAN_DETERMINISM.csv',[{'video_id':'DALI','positions_checked':0,'status':'NOT_RUN_WEIGHT_MISSING'},{'video_id':'HANGZHOU','positions_checked':0,'status':'NOT_RUN_WEIGHT_MISSING'},{'video_id':'WUHAN','positions_checked':0,'status':'NOT_RUN_WEIGHT_MISSING'}])
 (OUT/'FINAL_SCAN_PROXY_REPORT.md').write_text(f"# Final Scan/Proxy Report\n\nThis is a **NEW_PROSPECTIVE_PREREGISTRATION**, not a recovered historical contract. Protocol `{protocol['protocol_hash']}` was frozen before any scan or downstream result.\n\nExecution cannot start: expected bound weight `{model}` is absent from the repository and `/root`; the `ultralytics` runtime is also absent. No historical YOLO output was reused.\n")
 print(json.dumps({'status':'PROSPECTIVE_CONTRACT_FROZEN','protocol_hash':protocol['protocol_hash'],'weight_available':model.is_file()},sort_keys=True))
if __name__=='__main__':main()
